function check(bool $ok,string $label): void { global $checks; if(!$ok) throw new RuntimeException('FAIL: '.$label); $checks++; echo "PASS: $label\n"; }
function cli(array $args): string {
 global $root,$env;
 $p=proc_open([PHP_BINARY,$root.'/bin/api-key.php',...$args],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$root,$env);
 fclose($pipes[0]); $out=stream_get_contents($pipes[1]); $err=stream_get_contents($pipes[2]); fclose($pipes[1]); fclose($pipes[2]);
 if(proc_close($p)!==0) throw new RuntimeException('CLI failed: '.$err); return $out;
}
function new_key(string $name,string $scope='read'): string { preg_match('/agt_[a-f0-9]{64}/',cli(['create',$name,$scope]),$m); return $m[0]??''; }
function api(string $method,string $endpoint,?array $body=null,?string $auth=null,?string $raw=null,array $extra=[]): array {
 global $key;
 $headers=['Accept: application/json']; if(($auth??$key)!=='') $headers[]='Authorization: Bearer '.($auth??$key);
 if($body!==null||$raw!==null) $headers[]='Content-Type: application/json';
 $responseHeaders=[]; $c=curl_init('http://127.0.0.1:8099'.$endpoint);
 curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_TIMEOUT=>3,CURLOPT_HTTPHEADER=>[...$headers,...$extra],CURLOPT_HEADERFUNCTION=>function($c,$line) use (&$responseHeaders){$pair=explode(':',$line,2);if(count($pair)===2)$responseHeaders[strtolower(trim($pair[0]))]=trim($pair[1]);return strlen($line);}]);
 if($body!==null||$raw!==null) curl_setopt($c,CURLOPT_POSTFIELDS,$raw??json_encode($body));
 $text=curl_exec($c); $status=(int)curl_getinfo($c,CURLINFO_HTTP_CODE); unset($c);
 return [$status,json_decode((string)$text,true),$responseHeaders,(string)$text];
}
